const lv_image_dsc_t *HomeAppIcon(void)
{
    static lv_image_dsc_t dsc{};
    static bool ready = false;
    if (!ready) {
        dsc.header.magic = LV_IMAGE_HEADER_MAGIC;
        dsc.header.cf = LV_COLOR_FORMAT_ARGB8888;
        dsc.header.w = 128;
        dsc.header.h = 128;
        dsc.header.stride = 128 * 4;
        dsc.data_size = sizeof(kPx);
        dsc.data = kPx;
        ready = true;
    }
    return &dsc;
}
